style.css:
@-moz-document domain("facebook.com"), domain("messenger.com") {
body {
  background-color: #ffe6f2 !important;
  background-image: url("https://i.imgur.com/Yf6h4gO.png");
  background-size: cover !important;
  background-attachment: fixed !important;
  color: #ff69b4 !important;
  font-family: 'Comic Sans MS', 'Poppins', sans-serif !important;
}

/* Navigation bar */
header, [role="banner"] {
  background-color: #ffb6c1 !important;
  border-bottom: 2px solid #ff8dc7 !important;
}

/* Text & links */
a, span, div, p {
  color: #ff69b4 !important;
}
a:hover {
  color: #6ec6ff !important;
}

/* Messenger chat bubbles */
div[role="row"] div[dir="auto"] {
  font-family: 'Poppins', 'Comic Sans MS', sans-serif !important;
}

/* Received message bubble (blue) */
div[role="row"] div[style*="rgb(240, 242, 245)"] {
  background-color: #a6d8ff !important;
  color: #2a2a2a !important;
  border-radius: 20px !important;
  padding: 8px 12px !important;
}

/* Sent message bubble (pink) */
div[role="row"] div[style*="rgb(0, 132, 255)"] {
  background-color: #ffb6e6 !important;
  color: #2a2a2a !important;
  border-radius: 20px !important;
  padding: 8px 12px !important;
}

/* Input boxes */
textarea, input, [role="textbox"] {
  background-color: #fff0f7 !important;
  border: 1px solid #ffcce6 !important;
  color: #ff69b4 !important;
}

/* Buttons */
button {
  background-color: #ffcce6 !important;
  border: none !important;
  color: #ff1493 !important;
  border-radius: 10px !important;
}
button:hover {
  background-color: #ff99cc !important;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-thumb {
  background-color: #ff99cc;
  border-radius: 10px;
}
::-webkit-scrollbar-track {
  background-color: #ffe6f2;
}
}
